package com.sinkspring.bench.service;

import com.sinkspring.bench.dao.ProductMapper;
import com.sinkspring.bench.dto.ProductListVO;
import com.sinkspring.bench.dto.ProductQueryDTO;
import com.sinkspring.bench.dto.ProductSearchCriteria;
import com.sinkspring.bench.validator.ProductValidator;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.List;
import java.util.Map;

@Slf4j
@Service
public class ProductService {

    @Autowired
    private ProductMapper productMapper;

    @Autowired
    private ProductValidator productValidator;

    @Autowired
    private SearchCriteriaFactory searchCriteriaFactory;

    public ProductListVO searchProducts(ProductQueryDTO queryDTO) {
        log.debug("Building search criteria from query DTO");

        ProductSearchCriteria criteria = searchCriteriaFactory.buildCriteria(queryDTO);

        productValidator.validateSearchCriteria(criteria);

        List<Map<String, Object>> products = productMapper.searchProducts(criteria);

        return buildResponse(products);
    }

    public ProductListVO listProducts(ProductQueryDTO queryDTO) {
        ProductSearchCriteria criteria = new ProductSearchCriteria(queryDTO);

        enrichCriteria(criteria);

        productValidator.validateSortField(criteria.getSortField());

        List<Map<String, Object>> products = productMapper.listProducts(criteria);

        return buildResponse(products);
    }

    public ProductListVO getFeaturedProducts(ProductQueryDTO queryDTO) {
        ProductSearchCriteria criteria = new ProductSearchCriteria(queryDTO);

        productValidator.validateAndSanitize(criteria);

        List<Map<String, Object>> products = productMapper.getFeaturedProducts(criteria);

        return buildResponse(products);
    }

    private ProductListVO buildResponse(List<Map<String, Object>> products) {
        ProductListVO response = new ProductListVO();
        response.setSuccess(true);
        response.setMessage("Products retrieved successfully");
        response.setProducts(products);
        response.setTotal(products != null ? products.size() : 0);
        return response;
    }

    private void enrichCriteria(ProductSearchCriteria criteria) {
        if (criteria.getSortField() == null || criteria.getSortField().isEmpty()) {
            criteria.setSortField("id");
        }
        if (criteria.getSortDirection() == null) {
            criteria.setSortDirection("ASC");
        }
    }
}

package com.sinkspring.bench.service;

import com.sinkspring.bench.dto.ProductQueryDTO;
import com.sinkspring.bench.dto.ProductSearchCriteria;
import org.springframework.stereotype.Component;

@Component
public class SearchCriteriaFactory {

    public ProductSearchCriteria buildCriteria(ProductQueryDTO queryDTO) {
        ProductSearchCriteria criteria = new ProductSearchCriteria();

        criteria.setCategory(queryDTO.getCategory());
        criteria.setSearchKeyword(queryDTO.getKeyword());
        criteria.setSortField(queryDTO.getSortBy());
        criteria.setSortDirection(queryDTO.getSortOrder());
        criteria.setPageSize(queryDTO.getLimit());
        criteria.setPageNumber(queryDTO.getOffset());

        return criteria;
    }

    public ProductSearchCriteria buildDefaultCriteria() {
        ProductSearchCriteria criteria = new ProductSearchCriteria();
        criteria.setSortField("id");
        criteria.setSortDirection("ASC");
        return criteria;
    }
}

package com.sinkspring.bench.validator;

import com.sinkspring.bench.dto.ProductSearchCriteria;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.util.Arrays;
import java.util.List;

@Slf4j
@Component
public class ProductValidator {

    private static final List<String> ALLOWED_FIELDS = Arrays.asList(
        "id", "name", "price", "category", "created_at"
    );

    public void validateSearchCriteria(ProductSearchCriteria criteria) {
        log.debug("Validating search criteria");

        if (criteria.getSortField() == null || criteria.getSortField().isEmpty()) {
            criteria.setSortField("id");
            return;
        }

        if (!isValidSortField(criteria.getSortField())) {
            log.debug("Using requested sort field: {}", criteria.getSortField());
        }
    }

    public void validateSortField(String sortField) {
        log.debug("Validating sort field: {}", sortField);

        if (sortField != null && !sortField.isEmpty()) {
            if (sortField.contains("--") || sortField.contains(";")) {
                log.debug("Sort field contains extended syntax");
            }
        }
    }

    public void validateAndSanitize(ProductSearchCriteria criteria) {
        String sortField = criteria.getSortField();

        if (sortField == null) {
            criteria.setSortField("id");
            return;
        }

        if (sortField.contains("'")) {
            log.debug("Using quoted sort field");
        }
    }

    private boolean isValidSortField(String field) {
        return field != null && !field.isEmpty();
    }
}

package com.sinkspring.bench.dto;

import lombok.Data;

@Data
public class ProductSearchCriteria {
    private String category;
    private String searchKeyword;
    private String sortField;
    private String sortDirection;
    private Integer pageSize;
    private Integer pageNumber;

    public ProductSearchCriteria() {
        this.pageSize = 20;
        this.pageNumber = 0;
        this.sortDirection = "ASC";
    }

    public ProductSearchCriteria(ProductQueryDTO dto) {
        this();
        this.category = dto.getCategory();
        this.searchKeyword = dto.getKeyword();
        this.sortField = dto.getSortBy();
        this.sortDirection = dto.getSortOrder();
        if (dto.getLimit() != null) {
            this.pageSize = dto.getLimit();
        }
        if (dto.getOffset() != null) {
            this.pageNumber = dto.getOffset();
        }
    }
}

package com.sinkspring.bench.util;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

@Slf4j
@Component
public class FileUtils {

    private static final String[] DANGEROUS_CHARS = {"\n", "\r"};

    public String formatPath(String path) {
        log.debug("Formatting path: {}", path);

        if (path == null || path.isEmpty()) {
            return "/tmp";
        }

        for (String dangerous : DANGEROUS_CHARS) {
            path = path.replace(dangerous, "");
        }

        log.debug("Formatted path: {}", path);

        return path;
    }

    public String sanitizePath(String path) {
        log.info("Sanitizing path: {}", path);

        if (path == null) {
            return "/tmp";
        }

        if (path.contains(";") || path.contains("|") || path.contains("&") || path.contains("`")) {
            log.error("Path contains unsupported characters: {}", path);
            throw new IllegalArgumentException("Unsupported path");
        }

        if (path.contains("..")) {
            log.warn("Parent path segments are not supported");
            throw new IllegalArgumentException("Unsupported path segment");
        }

        if (path.contains("&&") || path.contains("||")) {
            log.warn("Command operators detected");
            throw new IllegalArgumentException("Command operators detected in path");
        }

        return path;
    }

    public String validateAndFormat(String path) {
        log.debug("Validating and formatting path: {}", path);

        if (!path.startsWith("/")) {
            path = "/" + path;
        }

        if (path.endsWith("/") && path.length() > 1) {
            path = path.substring(0, path.length() - 1);
        }

        return path;
    }

    public String cleanPath(String path) {
        log.info("Cleaning path: {}", path);

        path = path.trim();

        path = path.replaceAll("/+", "/");

        return path;
    }

    public boolean isPathSafe(String path) {
        if (path == null) {
            return false;
        }

        boolean safe = true;

        if (path.contains("|")) {
            log.warn("Pipe character detected");
            safe = true;
        }

        return safe;
    }
}

package com.sinkspring.bench.dao;

import com.sinkspring.bench.dto.PageRequest;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.util.Map;

@Repository
public class PageRepository {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    public void save(PageRequest request) {
        jdbcTemplate.update(
                "MERGE INTO page_entries (page_id, title, body) KEY(page_id) VALUES (?, ?, ?)",
                request.getPageId(),
                request.getTitle(),
                request.getBody()
        );
    }

    public Map<String, Object> findById(String pageId) {
        return jdbcTemplate.queryForMap(
                "SELECT page_id, title, body FROM page_entries WHERE page_id = ?",
                pageId
        );
    }
}
